// SPDX-License-Identifier: MIT

import * as React from "react"

import {
  getFlagSrcSet,
  getFlagUrl,
  type FlagFormat,
  type FlagRatio,
  type FlagWidth,
} from "./flag-utils"

export interface FlagProps
  extends Omit<React.ComponentProps<"img">, "src" | "srcSet" | "width" | "height"> {
  code: string
  format?: FlagFormat
  width?: FlagWidth | number
  ratio?: FlagRatio
  decorative?: boolean
}

export function Flag({
  code,
  format = "svg",
  width = 80,
  ratio = "4x3",
  decorative = false,
  alt,
  loading = "lazy",
  decoding = "async",
  sizes,
  className,
  style,
  ...props
}: FlagProps) {
  const src = getFlagUrl(code, { format, width, ratio })
  const srcSet = getFlagSrcSet(code, { format, width, ratio })
  const normalizedCode = code.trim().toLowerCase()
  const height = ratio === "original" ? undefined : ratio === "1x1" ? width : Math.round(width * 0.75)
  const aspectRatio = ratio === "original" ? undefined : ratio === "1x1" ? "1 / 1" : "4 / 3"

  return (
    <img
      {...props}
      data-slot="flag"
      data-code={normalizedCode}
      data-format={format}
      data-ratio={ratio}
      src={src}
      srcSet={srcSet}
      sizes={sizes ?? (srcSet ? `${width}px` : undefined)}
      width={width}
      height={height}
      alt={decorative ? "" : (alt ?? `${code.toUpperCase()} flag`)}
      aria-hidden={decorative || undefined}
      loading={loading}
      decoding={decoding}
      className={className}
      style={{
        display: "block",
        maxWidth: "100%",
        ...(aspectRatio ? { aspectRatio, objectFit: "cover" as const } : {}),
        ...style,
      }}
    />
  )
}

// SPDX-License-Identifier: MIT

export const flagFormats = ["svg", "png", "webp"] as const
export type FlagFormat = (typeof flagFormats)[number]

export const flagWidths = [20, 40, 80, 160, 320, 640, 1280, 2560] as const
export type FlagWidth = (typeof flagWidths)[number]
export const flagRatios = ["4x3", "1x1", "original"] as const
export type FlagRatio = (typeof flagRatios)[number]

export const flagIconWidths = [
  16, 20, 24, 28, 32, 36, 40, 48, 56, 60, 64, 72, 80, 84, 96, 108, 112,
  120, 128, 144, 160, 192, 224, 256,
] as const

export interface FlagUrlOptions {
  format?: FlagFormat
  width?: FlagWidth | number
  ratio?: FlagRatio
}

export function normalizeFlagCode(code: string) {
  const normalizedCode = code.trim().toLowerCase()
  if (!/^[a-z]{2}(?:-[a-z0-9]{2,3})?$/.test(normalizedCode)) {
    throw new Error(`Invalid flag code: ${code}`)
  }
  return normalizedCode
}

export function getFlagUrl(code: string, options: FlagUrlOptions = {}) {
  const normalizedCode = normalizeFlagCode(code)
  const format = options.format ?? "svg"
  const width = options.width ?? 80
  const ratio = options.ratio ?? "4x3"
  validateFlagWidth(width)

  if (format === "svg") {
    return `https://flagcdn.com/${normalizedCode}.svg`
  }

  if (ratio !== "original" && width <= flagIconWidths.at(-1)!) {
    const iconWidth = closestWidth(width, flagIconWidths)
    return `https://flagcdn.com/${iconWidth}x${Math.round(iconWidth * 0.75)}/${normalizedCode}.${format}`
  }

  return `https://flagcdn.com/w${closestWidth(width, flagWidths)}/${normalizedCode}.${format}`
}

export function getFlagSrcSet(code: string, options: FlagUrlOptions = {}) {
  const format = options.format ?? "svg"
  if (format === "svg") return undefined

  const ratio = options.ratio ?? "4x3"
  const requestedWidth = options.width ?? 80
  validateFlagWidth(requestedWidth)
  const availableWidths = ratio === "original" ? flagWidths : flagIconWidths
  const candidates = [requestedWidth, requestedWidth * 2, requestedWidth * 3]
    .map((candidate) => closestWidth(candidate, availableWidths))
    .filter((candidate, index, values) => values.indexOf(candidate) === index)

  return candidates
    .map((candidate) => `${getFlagUrl(code, { ...options, width: candidate, ratio })} ${candidate}w`)
    .join(", ")
}

function closestWidth<T extends number>(width: number, widths: readonly T[]): T {
  return widths.reduce((closest, candidate) =>
    Math.abs(candidate - width) < Math.abs(closest - width) ? candidate : closest,
  )
}

function validateFlagWidth(width: number) {
  if (!Number.isFinite(width) || width <= 0) {
    throw new Error(`Flag width must be a positive finite number: ${width}`)
  }
}

// SPDX-License-Identifier: MIT

import * as React from "react"

import { cn } from "@/lib/utils"

import { Flag } from "./flag"
import { flagNames, flags, type FlagCode, type FlagKind } from "./flag-data"
import type { FlagFormat, FlagRatio } from "./flag-utils"

export interface FlagPickerProps {
  value?: FlagCode
  defaultValue?: FlagCode
  onValueChange?: (code: FlagCode) => void
  format?: FlagFormat
  ratio?: FlagRatio
  placeholder?: string
  searchPlaceholder?: string
  emptyMessage?: string
  kinds?: FlagKind[]
  disabled?: boolean
  className?: string
  name?: string
}

export function FlagPicker({
  value,
  defaultValue,
  onValueChange,
  format = "svg",
  ratio = "4x3",
  placeholder = "Select a flag",
  searchPlaceholder = "Search by name or code…",
  emptyMessage = "No flags found.",
  kinds,
  disabled = false,
  className,
  name,
}: FlagPickerProps) {
  const [internalValue, setInternalValue] = React.useState<FlagCode | undefined>(defaultValue)
  const [open, setOpen] = React.useState(false)
  const [query, setQuery] = React.useState("")
  const [activeIndex, setActiveIndex] = React.useState(0)
  const rootRef = React.useRef<HTMLDivElement>(null)
  const triggerRef = React.useRef<HTMLButtonElement>(null)
  const searchRef = React.useRef<HTMLInputElement>(null)
  const listId = React.useId()
  const currentValue = value ?? internalValue

  const filteredFlags = React.useMemo(() => {
    const normalizedQuery = query.trim().toLocaleLowerCase()
    return flags.filter((flag) => {
      const inKind = !kinds?.length || kinds.includes(flag.kind)
      const matches = !normalizedQuery
        || flag.name.toLocaleLowerCase().includes(normalizedQuery)
        || flag.code.includes(normalizedQuery)
      return inKind && matches
    })
  }, [kinds, query])

  React.useEffect(() => {
    if (!open) return
    const onPointerDown = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false)
    }
    document.addEventListener("pointerdown", onPointerDown)
    return () => document.removeEventListener("pointerdown", onPointerDown)
  }, [open])

  React.useEffect(() => {
    if (!open) return
    requestAnimationFrame(() => searchRef.current?.focus())
  }, [open])

  function selectFlag(code: FlagCode) {
    if (value === undefined) setInternalValue(code)
    onValueChange?.(code)
    setQuery("")
    setOpen(false)
    requestAnimationFrame(() => triggerRef.current?.focus())
  }

  function handleKeyDown(event: React.KeyboardEvent) {
    if (event.key === "Escape") {
      setOpen(false)
      requestAnimationFrame(() => triggerRef.current?.focus())
      return
    }
    if (event.key === "ArrowDown") {
      event.preventDefault()
      setActiveIndex((index) => Math.min(index + 1, filteredFlags.length - 1))
    }
    if (event.key === "ArrowUp") {
      event.preventDefault()
      setActiveIndex((index) => Math.max(index - 1, 0))
    }
    if (event.key === "Enter" && filteredFlags[activeIndex]) {
      event.preventDefault()
      selectFlag(filteredFlags[activeIndex].code)
    }
  }

  function toggleOpen() {
    const nextOpen = !open
    if (nextOpen) setActiveIndex(0)
    setOpen(nextOpen)
  }

  return (
    <div ref={rootRef} data-slot="flag-picker" className={cn("relative w-full", className)}>
      {name ? <input type="hidden" name={name} value={currentValue ?? ""} /> : null}
      <button
        ref={triggerRef}
        type="button"
        role="combobox"
        aria-expanded={open}
        aria-controls={listId}
        aria-haspopup="listbox"
        disabled={disabled}
        className={cn(
          "border-input bg-background ring-offset-background flex h-9 w-full items-center justify-between rounded-md border px-3 text-sm shadow-xs outline-none transition-[color,box-shadow]",
          "focus-visible:border-ring focus-visible:ring-ring/30 focus-visible:ring-[3px]",
          "disabled:cursor-not-allowed disabled:opacity-50",
        )}
        onClick={toggleOpen}
        onKeyDown={(event) => {
          if (!open && (event.key === "ArrowDown" || event.key === "Enter" || event.key === " ")) {
            event.preventDefault()
            setActiveIndex(0)
            setOpen(true)
          }
        }}
      >
        <span className={cn("flex min-w-0 items-center gap-2", !currentValue && "text-muted-foreground")}>
          {currentValue ? (
            <Flag
              code={currentValue}
              format={format}
              width={24}
              ratio={ratio}
              alt=""
              decorative
              className="size-5 rounded-[2px] object-cover shadow-[0_0_0_1px_rgba(0,0,0,0.12)]"
            />
          ) : null}
          <span className="truncate">{currentValue ? flagNames[currentValue] : placeholder}</span>
        </span>
        <ChevronDownIcon aria-hidden="true" className="text-muted-foreground size-4 shrink-0" />
      </button>

      {open ? (
        <div
          className="bg-popover text-popover-foreground absolute z-50 mt-1 w-full min-w-64 overflow-hidden rounded-md border shadow-md"
          onKeyDown={handleKeyDown}
        >
          <div className="border-b p-2">
            <div className="relative">
              <SearchIcon
                aria-hidden="true"
                className="text-muted-foreground pointer-events-none absolute start-2.5 top-1/2 size-4 -translate-y-1/2"
              />
              <input
                ref={searchRef}
                value={query}
                onChange={(event) => {
                  setQuery(event.target.value)
                  setActiveIndex(0)
                }}
                placeholder={searchPlaceholder}
                aria-label={searchPlaceholder}
                className="placeholder:text-muted-foreground h-9 w-full rounded-sm bg-transparent ps-8 pe-3 text-sm outline-none"
              />
            </div>
          </div>
          <div id={listId} role="listbox" className="max-h-72 overflow-y-auto p-1">
            {filteredFlags.length ? filteredFlags.map((flag, index) => (
              <button
                key={flag.code}
                type="button"
                role="option"
                aria-selected={currentValue === flag.code}
                data-active={index === activeIndex || undefined}
                className="data-[active]:bg-accent data-[active]:text-accent-foreground flex w-full items-center gap-2 rounded-sm px-2 py-2 text-start text-sm outline-none hover:bg-accent hover:text-accent-foreground"
                onPointerMove={() => setActiveIndex(index)}
                onClick={() => selectFlag(flag.code)}
              >
                <Flag
                  code={flag.code}
                  format={format}
                  width={24}
                  ratio={ratio}
                  alt=""
                  decorative
                  className="h-[15px] w-5 shrink-0 rounded-[2px] object-cover shadow-[0_0_0_1px_rgba(0,0,0,0.12)]"
                />
                <span className="min-w-0 flex-1 truncate">{flag.name}</span>
                <span className="text-muted-foreground font-mono text-[11px] uppercase">{flag.code}</span>
                <CheckIcon
                  aria-hidden="true"
                  className={cn("size-4", currentValue === flag.code ? "opacity-100" : "opacity-0")}
                />
              </button>
            )) : (
              <p className="text-muted-foreground px-3 py-8 text-center text-sm">{emptyMessage}</p>
            )}
          </div>
        </div>
      ) : null}
    </div>
  )
}

function ChevronDownIcon(props: React.ComponentProps<"svg">) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...props}>
      <path d="m6 9 6 6 6-6" />
    </svg>
  )
}

function SearchIcon(props: React.ComponentProps<"svg">) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...props}>
      <circle cx="11" cy="11" r="8" />
      <path d="m21 21-4.35-4.35" />
    </svg>
  )
}

function CheckIcon(props: React.ComponentProps<"svg">) {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...props}>
      <path d="m5 12 4 4L19 6" />
    </svg>
  )
}

